// === Tab: mySketch ===
let colors = ["#f2eb8a", "#fed000", "#fc8405", "#ed361a", "#e2f0f3", "#b3dce0", "#4464a1", "#203051", "#ffc5c7", "#f398c3", "#cf3895", "#6d358a", "#06b4b0", "#4b8a5f"];

let mySeed;

function setup() {
	createCanvas(1000,1000);
	colorMode(HSB, 360, 100, 100, 100);
	mySeed = floor(random(1,1000000));
	rectMode(CENTER);
	ellipseMode(CENTER);
	strokeCap(SQUARE);
	fill(100);
	rect(width/2,height/2,width,height);
	colorMode(HSB,360, 100, 100, 100);
}


function draw() {
	randomSeed(mySeed);
	let mySize=200;
	for(let x=mySize;x <= width-mySize;x+=(Math.max(0.001, Math.abs(mySize)) || 1))
	{
		for(let y=mySize;y <= height-mySize;y+=(Math.max(0.001, Math.abs(mySize)) || 1))
		{
			setGradientFill(createVector(x,y),mySize/2);
			stroke(0.05);
			square(x,y,mySize);
      drawArc(x,y,mySize/2);
		}
	} 
}


function drawCircle(x,y)
{
	for(let x=0;x < width;x+=100)
	{
		for(let y=0;y < height;y+=100)
		{
      drawArc(x,y);
		}
	} 

}


function drawArc(x,y,mySize)
{
	 let w = mySize;
	 let h = mySize;
	 let ang = PI;
	 let sx = random(0.5,1.5);
	 let sy = random(0.5,1.5);
	 push();
	 translate(x,y);
	 rotate(random([0,PI/2,PI,3*PI/2]));
	 let thick = mySize/2;
	 setGradientStroke(createVector(0,0),thick*2);
	 strokeWeight(thick);
   arc(0,0,w,h,PI,ang+PI);
	 pop();

}


function generateColor(scale) {
	let temp = color(colors[floor(random(0, colors.length))]);
	myColor = color(hue(window.color(temp)) + randomGaussian() * scale,
		saturation(window.color(temp)) + randomGaussian()*scale,
		brightness(window.color(temp)) + randomGaussian()*scale,
		random(10,100));
	return myColor;
}



function setGradientStroke(pos,rad)
{
	gradient = drawingContext.createRadialGradient(pos.x,pos.y,0,pos.x,pos.y,rad);
	gradient.addColorStop(0,generateColor(1));
	gradient.addColorStop(0.5,generateColor(1));
	gradient.addColorStop(1,generateColor(1));
	drawingContext.strokeStyle = gradient;
}

function setGradientFill(pos,rad)
{
	gradient = drawingContext.createRadialGradient(pos.x,pos.y,0,pos.x,pos.y,rad);
	gradient.addColorStop(0,generateColor(1));
	gradient.addColorStop(0.5,generateColor(1));
	gradient.addColorStop(1,generateColor(1));
	drawingContext.fillStyle = gradient;
}
